/// 🧭️ Describes a retained allocation outcome without moving its original causes.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum NativeEncodeAllocationOutcomeStatus{Absent,Canceled,Accepted,Refused}
/// 👁️ Inspects the caller-owned original allocation outcome.
pub fn native_encode_allocation_outcome_status(slot:&Option<NativeEncodeAllocationOutcome>)->NativeEncodeAllocationOutcomeStatus{let Some(outcome)=slot.as_ref()else{return NativeEncodeAllocationOutcomeStatus::Absent};if allocation_failed(outcome){NativeEncodeAllocationOutcomeStatus::Refused}else if outcome.admitted{NativeEncodeAllocationOutcomeStatus::Accepted}else{NativeEncodeAllocationOutcomeStatus::Canceled}}
/// 🔎️ Describes the retained original settlement without moving any refusal.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum NativeEncodeEffectSettlementStatus{Absent,Pending,Accepted,Refused}
/// 👁️ Inspects a caller-owned settlement without moving its original causes.
pub fn native_encode_effect_settlement_status(slot:&Option<NativeEncodeEffectSettlement>)->NativeEncodeEffectSettlementStatus{
 let Some(state)=slot.as_ref()else{return NativeEncodeEffectSettlementStatus::Absent};if state.progress().is_none()||state.work_phase()!=NativeEncodeEffectPostPhase::Completed||state.physical_phase()!=NativeEncodeEffectPostPhase::Completed{return NativeEncodeEffectSettlementStatus::Pending}let(work,physical,invariant)=state.failures();if work.is_some()||state.work_overrun().is_some()||state.marker_failure().is_some()||physical.is_some()||state.has_physical_receipt()||invariant.is_some(){NativeEncodeEffectSettlementStatus::Refused}else{NativeEncodeEffectSettlementStatus::Accepted}
}
fn run_closure_effect(settlement:&NativeEncodeEffectSettlement,work:&mut crate::OriginalWorkTurn<'_,'_>,receipt:&mut Option<semio_framework_value_control_contract::OriginalWorkPerformedReceipt>,claim:&mut Option<Result<u128,ValueError>>,grant:RetainedCloneGrant,actual:&mut Option<usize>,run:impl FnOnce(&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->Result<(),ValueError>)->Result<Result<(),ValueError>,ValueError>{
 settlement.issue_performed(work,receipt)?;let mut guard=PerformedClaim{work,settlement,receipt,claim};
 let output={let sink=guard.receipt.as_mut().expect("original performed receipt issued");let mut effect=semio_framework_value_control_contract::RetainedAllocationEffect::new(grant,u64::MAX,actual,sink);run(&mut effect)};drop(guard);Ok(output)
}
/// 🧾️ Settles the claimed receipt and records the physical marker before any allocation Post.
fn settle_closure_work(settlement:&mut NativeEncodeEffectSettlement,work:&mut crate::OriginalWorkTurn<'_,'_>,partial:&mut Option<semio_framework_value_control_contract::OriginalWorkPartialOutcome>,physical:RetainedCloneProgress,actual:Option<usize>)->Result<bool,ValueError>{
 if settlement.work_phase()==NativeEncodeEffectPostPhase::Completed{let recorded=settlement.recorded_performed().unwrap_or(true);return settlement.record_performed_before_post(work,physical,recorded,actual)}
 let pending=settlement.performed_pending(work)?;if pending&&partial.is_none()&&!settlement.settle_performed_into(work,partial)?{return Ok(false)}
 settlement.record_performed_before_post(work,physical,pending||partial.is_some(),actual)
}
