fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl NativeEncodeControl<'_>{
 /// 🪢️ Runs one closure inside one original Work action on this control's own recipient; `None` means the quote was not admitted and nothing ran or was charged. The control handed to the closure carries the live work action: children may charge, checkpoint and read bytes but must never prepare_work.
 pub fn with_effect<R>(&mut self,grant:RetainedCloneGrant,maximum_work:u64,run:impl FnOnce(&mut Self,&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->R)->Result<Option<R>,ValueError>{
  let Some(mut open)=semio_framework_value_control_contract::OriginalEffectRun::begin(&mut self.action,grant,maximum_work)?else{return Ok(None)};
  let output={let mut effect=open.effect()?;run(self,&mut effect)};
  open.finish(&mut self.action,&mut 0)?;Ok(Some(output))
 }
 /// 🎟️ Starts the original effect settlement with the work its selected action quotes.
 pub fn begin_effect_settlement_with_work(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>,demand:RetirementDemand,maximum_work:u64)->Result<bool,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).begin_with_work(slot,demand,maximum_work)}
}
pub(super) fn remaining(grant:RetainedCloneGrant,used:RetainedCloneProgress)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:grant.maximum_items.saturating_sub(used.copied_items),maximum_copy_bytes:grant.maximum_copy_bytes.saturating_sub(used.copied_bytes),maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(used.retained_capacity_bytes),maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(used.released_bytes),maximum_depth:grant.maximum_depth}}
pub(super) fn admits(grant:RetainedCloneGrant,demand:RetainedCloneGrant)->bool{demand.maximum_items<=grant.maximum_items&&demand.maximum_copy_bytes<=grant.maximum_copy_bytes&&demand.maximum_capacity_bytes<=grant.maximum_capacity_bytes&&demand.maximum_release_bytes<=grant.maximum_release_bytes&&demand.maximum_depth<=grant.maximum_depth}
fn allocation_failed(outcome:&NativeEncodeAllocationOutcome)->bool{outcome.primary.is_some()||outcome.forwarded_quote.is_some()||outcome.scoped_quote.is_some()||outcome.extent_refusal.is_some()||outcome.forwarded_refusal.is_some()||outcome.scoped_refusal.is_some()}
